"use client";
import Link from "next/link";
import { useEffect, useState } from "react";
import { courses, interestOptions, Profile, researchAreas } from "@/lib/data";
import { useApp } from "./app-provider";
import { Icon } from "./icon";
import { SaveCourse } from "./course-card";
export function ProfilePage(){
  const {profile,setProfile,saved,savedResearch,toggleResearch,toast,ready}=useApp();
  const [draft,setDraft]=useState<Profile>(profile);const [dirty,setDirty]=useState(false);
  useEffect(()=>{if(!dirty)setDraft(profile);},[profile,dirty]);
  function update<K extends keyof Profile>(key:K,value:Profile[K]){setDirty(true);setDraft(p=>({...p,[key]:value}));}
  return <div className="page profile-page"><section className="page-heading"><div><div className="eyebrow"><span/>A PATH THAT FEELS LIKE YOU</div><h1>Your interests. <em>Your direction.</em></h1><p>A little about you helps us make better connections.</p></div></section>
    <div className="profile-layout"><form className="panel profile-form" onSubmit={e=>{e.preventDefault();setProfile({...draft,name:draft.name.trim(),program:draft.program.trim()});setDirty(false);toast("Profile saved. Your course recommendations are updated.");}}>
      <div className="panel-heading"><span className="panel-icon"><Icon name="user"/></span><div><h2>Make yourself at home</h2><p>Your preferences stay in this browser.</p></div></div>
      <div className="form-grid"><label>Your name<input required maxLength={80} value={draft.name} onChange={e=>update("name",e.target.value)} placeholder="Your name"/></label><label>Program or major<input maxLength={120} value={draft.program} onChange={e=>update("program",e.target.value)} placeholder="e.g. Computer Science"/></label></div>
      <fieldset><legend>What are you curious about?</legend><p className="field-help">Pick a few interests. You can always change them.</p><div className="interest-options">{interestOptions.map(interest=><button type="button" key={interest} className={`interest-option ${draft.interests.includes(interest)?"picked":""}`} aria-pressed={draft.interests.includes(interest)} onClick={()=>update("interests",draft.interests.includes(interest)?draft.interests.filter(v=>v!==interest):[...draft.interests,interest])}>{draft.interests.includes(interest)&&<Icon name="check" size={14}/>} {interest}</button>)}</div></fieldset>
      <fieldset><legend>How do you like to learn?</legend><div className="assessment-options">{(["Projects","Exams","No preference"] as const).map(item=><label key={item} className={`choice-card ${draft.assessment===item?"picked":""}`}><input type="radio" name="assessment" value={item} checked={draft.assessment===item} onChange={()=>update("assessment",item)}/><span><strong>{item}</strong><small>{item==="Projects"?"Build and apply ideas":item==="Exams"?"Learn, practice, demonstrate":"Keep my options open"}</small></span></label>)}</div></fieldset>
      <label className="range-label"><span>Preferred weekly workload <strong>{draft.workload} hrs / course</strong></span><input type="range" min={6} max={20} step={1} value={draft.workload} onChange={e=>update("workload",Number(e.target.value))}/><span className="range-labels"><small>6 hours · lighter</small><small>20 hours · intensive</small></span></label>
      <fieldset><legend>Courses you’ve completed</legend><p className="field-help">Used for sample prerequisite checks and to avoid recommending completed courses.</p><div className="completed-options">{courses.map(c=><label key={c.id}><input type="checkbox" checked={draft.completed.includes(c.id)} onChange={()=>update("completed",draft.completed.includes(c.id)?draft.completed.filter(id=>id!==c.id):[...draft.completed,c.id])}/><span>{c.id}<small>{c.title}</small></span></label>)}</div></fieldset>
      <label>What would you like to work toward?<textarea maxLength={800} rows={3} value={draft.goal} onChange={e=>update("goal",e.target.value)} placeholder="A research interest, a skill, or a direction you want to explore…"/><span className="field-help">Saved for your planning. Demo ranking uses the structured preferences above.</span></label>
      <div className="form-footer"><span>{dirty?"You have unsaved changes.":"You’re all set to explore."}</span><button className="btn primary" disabled={!ready} type="submit">Save preferences <Icon name="arrow" size={16}/></button></div>
    </form><aside className="profile-aside"><div className="profile-summary panel"><span className="large-avatar">{draft.name.trim().slice(0,1).toUpperCase()||"T"}</span><h2>{draft.name||"Your next chapter"}</h2><p>{draft.program||"Curious Trojan"}</p><div className="summary-stats"><div><strong>{draft.interests.length}</strong><span>Interests</span></div><div><strong>{saved.length}</strong><span>Saved courses</span></div><div><strong>{savedResearch.length}</strong><span>Research paths</span></div></div></div><div className="advice-note"><Icon name="spark" size={25}/><h3>You don’t need to have it all figured out.</h3><p>Start with what interests you. Your path can change as you learn.</p><Link href="/chat" className="text-button">Talk it through <Icon name="arrow" size={15}/></Link></div></aside></div>
    <section id="saved" className="saved-section"><div className="section-heading"><div><div className="section-title"><Icon name="bookmark" size={21}/><h2>My saved path</h2><span className="count-pill">{saved.length+savedResearch.length} saved</span></div><p>Keep your next possibilities close.</p></div></div>{saved.length+savedResearch.length===0?<div className="empty-state compact"><Icon name="bookmark" size={28}/><h3>A little room for possibility.</h3><p>Save courses and research directions as you explore.</p><Link href="/courses" className="btn secondary">Explore courses <Icon name="arrow" size={16}/></Link></div>:<div className="saved-grid">{saved.map(id=>courses.find(c=>c.id===id)).filter(c=>!!c).map(course=><article className="saved-item panel" key={course.id}><span className={`course-icon ${course.color}`}><Icon name={course.icon}/></span><div><small>{course.id} · COURSE</small><h3><Link href={`/courses/${course.slug}`}>{course.title}</Link></h3></div><SaveCourse course={course} compact/></article>)}{savedResearch.map(id=>researchAreas.find(r=>r.id===id)).filter(r=>!!r).map(area=><article className="saved-item panel" key={area.id}><span className={`course-icon ${area.color}`}><Icon name="flask"/></span><div><small>RESEARCH DIRECTION · DEMO</small><h3><Link href={`/research#${area.id}`}>{area.title}</Link></h3></div><button className="icon-button is-saved" aria-label={`Remove ${area.title} from saved path`} onClick={()=>toggleResearch(area.id)}><Icon name="check" size={17}/></button></article>)}</div>}</section>
  </div>;
}
